with flagged as (select *, case when lag(paid_at) over (partition by method order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by method order by paid_at, id) + interval '60' day then 1 else 0 end as is_new_session from payments), sessions_payments as (select *, sum(is_new_session) over (partition by method order by paid_at, id rows between unbounded preceding and current row) as island_id from flagged) select case when island_id >= 7 then 'LARGE' else 'SMALL' end as island_id_tier, sum(is_new_session) as total_is_new_session, count_if(status = 'REFUNDED') as refunded_events, count(case when status = 'SUCCESS' then 1 end) as success_count, sum(island_id) filter (where method = 'promptpay') as promptpay_total_island_id from sessions_payments group by island_id_tier order by island_id_tier desc;
